<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Database;
final class QueueService{
 public static function rebuild():int{
  $pdo=Database::connection();$settings=[];foreach($pdo->query("SELECT setting_key,setting_value FROM system_settings WHERE setting_key LIKE 'queue.%'")->fetchAll() as $x)$settings[$x['setting_key']]=(float)$x['setting_value'];
  $d7=(int)($settings['queue.fresh_days']??7);$d15=max($d7+1,(int)($settings['queue.fresh_days_15']??15));$d30=max($d15+1,(int)($settings['queue.fresh_days_30']??30));$minSources=max(1,(int)($settings['queue.min_sources']??2));$spreadThreshold=max(0.01,(float)($settings['queue.spread_percent']??20)/100);$s7=(float)($settings['queue.score_fresh_7']??25);$s15=(float)($settings['queue.score_fresh_15']??50);$s30=(float)($settings['queue.score_fresh_30']??80);
  
  $sql="WITH latest AS(SELECT * FROM(SELECT pp.*,ROW_NUMBER() OVER(PARTITION BY product_id,source_no ORDER BY price_received_at DESC,id DESC) rn FROM product_prices pp)x WHERE rn=1),s AS(SELECT p.id,p.expected_sources,p.min_sources,p.importance,MAX(l.price_received_at) latest_date,COUNT(l.id) source_count,MIN(l.unit_price) min_price,MAX(l.unit_price) max_price,AVG(l.unit_price) avg_price FROM products p LEFT JOIN latest l ON l.product_id=p.id WHERE p.status='active' AND p.is_active=1 GROUP BY p.id,p.expected_sources,p.min_sources,p.importance) SELECT * FROM s WHERE latest_date IS NULL OR DATEDIFF(DAY,latest_date,SYSDATETIME())>=:d7 OR source_count<:mins OR (avg_price>0 AND (max_price-min_price)/avg_price>=:spread)";
  $q=$pdo->prepare($sql);$q->execute(['d7'=>$d7,'mins'=>$minSources,'spread'=>$spreadThreshold]);$rows=$q->fetchAll();
  $up=$pdo->prepare("UPDATE price_queue SET score=:s,priority_level=:l,reason=:r,status='new',assigned_to=NULL,due_at=NULL,started_at=NULL,completed_at=NULL,result_note=NULL,updated_at=SYSDATETIME() WHERE product_id=:p AND status IN('new','completed','needs_followup')");
$ins=$pdo->prepare("INSERT INTO price_queue(product_id,score,priority_level,reason,status) SELECT :p,:s,:l,:r,'new' WHERE NOT EXISTS(SELECT 1 FROM price_queue WHERE product_id=:pc)");

  foreach($rows as $r){$fresh=100;$days=null;if($r['latest_date']!==null){$days=max(0,(int)((time()-strtotime($r['latest_date']))/86400));$fresh=$days>=$d30?$s30:($days>=$d15?$s15:($days>=$d7?$s7:0));}$missing=max(0,(int)$r['expected_sources']-(int)$r['source_count'])*15;$spread=0;if((float)$r['avg_price']>0){$x=((float)$r['max_price']-(float)$r['min_price'])/(float)$r['avg_price'];$spread=$x>=.20?30:($x>=.10?15:($x>=.05?8:0));}$mult=match((int)$r['importance']){3=>1.5,2=>1.25,default=>1.0};$score=($fresh+$missing+$spread)*$mult;$level=$score>=100?'critical':($score>=75?'very_high':($score>=50?'high':($score>=25?'medium':'normal')));$reason=[];if($r['latest_date']===null)$reason[]='بدون قیمت';if($days!==null&&$days>=$d30)$reason[]='قیمت قدیمی';if((int)$r['source_count']<(int)$r['min_sources'])$reason[]='منابع کمتر از حداقل';if($missing>0)$reason[]='منابع مورد انتظار ناقص';if($spread>0)$reason[]='اختلاف قیمت';$up->execute(['p'=>$r['id'],'s'=>$score,'l'=>$level,'r'=>implode('، ',$reason)]);if($up->rowCount()===0)$ins->execute(['p'=>$r['id'],'pc'=>$r['id'],'s'=>$score,'l'=>$level,'r'=>implode('، ',$reason)]);}return count($rows);
 }
}